let officeSection='home';
const officeHub=document.createElement('section');officeHub.id='officeHub';officeHub.hidden=!officeMode;officeHub.innerHTML=`<div class="officeIntro"><div><span class="eyebrow">COASTYOUTH RETAIL OFFICE</span><h1 id="officeHeading">Retail administration</h1><p>Configure your store. Keep checkout focused.</p></div><span class="officeConnected">● Shared Operations server</span></div><div id="officeTiles"></div><section id="officeWork" hidden><button id="officeBack" type="button">‹ Back to menu</button><h2 id="officeWorkTitle"></h2><div id="officeForms"></div><div id="officeCatalog"></div></section>`;posPanel.append(officeHub);
const officeNav=document.createElement('nav');officeNav.id='officeNav';officeNav.hidden=!officeMode;officeNav.setAttribute('aria-label','OFFICE sections');officeNav.innerHTML=officeSections.map(([id,label,icon])=>`<button type="button" data-office-section="${id}"><span aria-hidden="true">${icon}</span>${label}</button>`).join('');document.querySelector('.sidebar').insertBefore(officeNav,$('navCheckout'));
function officeRenderCatalog(){if(!officeMode||!posOverview)return;const products=posOverview.products;$('officeCatalog').innerHTML='<h3>Catalog · '+products.length+' products</h3><p>Groups become category buttons in DESK.</p><table><thead><tr><th>Product</th><th>Group</th><th>Price</th><th>Tax</th></tr></thead><tbody>'+products.map(x=>`<tr><td>${esc(x.name)}<small class="flowLineNote">${esc(flowLineDetails(x))}</small></td><td>${esc(x.category)}</td><td>${posMoney(x.price)}</td><td>${x.taxable?'Taxable':'Non-taxable'}</td></tr>`).join('')+'</tbody></table>';}
function officeRender(){if(!officeMode)return;const allowed=officeCards.filter(x=>(x.action==='timekeeping-manage'?['edit_time_cards','add_time_cards','manage_staff_schedule','export_payroll','manage_work_sites','review_requests'].some(can):x.action==='labor-reports'?['edit_time_cards','add_time_cards','export_payroll'].some(can):x.permission==='admin'?user?.admin:can(x.permission))&&(['users','roles','server','updates','labor-reports','schedule-report','login-security','review-communications','timekeeping-manage'].includes(x.action)||can('use_pos')));$('officeHeading').textContent=officeSection==='home'?'Retail administration':officeSections.find(x=>x[0]===officeSection)[1];$('officeTiles').innerHTML=allowed.filter(x=>officeSection==='home'||x.section===officeSection).map(x=>`<button type="button" class="officeTile" data-office-action="${x.action}"><span class="officeIcon" aria-hidden="true">${x.icon}</span><span><strong>${x.title}</strong><small>${x.description}</small></span><span aria-hidden="true">›</span></button>`).join('')||'<p>No tools are enabled for your role in this section.</p>';for(const b of officeNav.querySelectorAll('button'))b.setAttribute('aria-current',b.dataset.officeSection===officeSection?'page':'false');}
function officeHome(section='home'){if(!navigationAllowed())return;if(unfinished()){posMessage('Save or clear the current form before switching OFFICE sections.');return;}officeSection=section;$('officeWork').hidden=true;$('officeTiles').hidden=false;officeRender();}
async function openRetailOffice(){if(!navigationAllowed()||unfinished()){posMessage('Save or clear unfinished entries before opening OFFICE.');return;}if(window.pywebview?.api?.open_operations){const r=await window.pywebview.api.open_operations('office');if(r.error)posMessage(r.error);}else window.open('/office','_blank','noopener');}
async function officeAction(action){if($('flowOffice'))$('flowOffice').hidden=true;if(flowActions.includes(action)||action==='catalog'){await flowOffice(action==='catalog'?'product-tools':action);return;}if(['layouts','terminals'].includes(action)){await retailEditor(action);return;}if($('retailEditor'))$('retailEditor').hidden=true;if(!navigationAllowed())return;if(action==='users'){if(unfinished()){posMessage('Save or clear the current form first.');return;}$('officeTiles').hidden=true;$('officeWork').hidden=false;$('officeWorkTitle').textContent='Users';$('officeForms').hidden=true;$('officeCatalog').hidden=true;$('officeUsers').hidden=false;await officeLoadUsers();return;}if(action==='catalog'||action==='receipt'){if(unfinished()){posMessage('Save or clear the current form first.');return;}$('officeTiles').hidden=true;$('officeWork').hidden=false;$('officeUsers').hidden=true;$('officeForms').hidden=false;$('officeWorkTitle').textContent=action==='catalog'?'Products & groups':'Receipt & tax';$('posProduct').hidden=action!=='catalog';$('posSetup').hidden=action!=='receipt';$('officeCatalog').hidden=action!=='catalog';officeRenderCatalog();return;}if(action==='accounts'){$('creditOpen').click();return;}if(action==='history'){$('posHistory').click();return;}if(action==='updates'){$('openPosUpdates').click();return;}if(action==='cards'){posMessage('Credit cards will be added in future updates.');return;}const urls={users:'/#retail-users',roles:'/#retail-roles',server:'/#settings'};if(urls[action]){if(unfinished()){posMessage('Save or clear unfinished work first.');return;}if(window.pywebview?.api?.open_operations){const result=await window.pywebview.api.open_operations(action);if(result.error)posMessage(result.error);}else window.open(urls[action],'_blank','noopener');}}
officeNav.onclick=e=>{const b=e.target.closest('[data-office-section]');if(b)officeHome(b.dataset.officeSection);};$('officeTiles').onclick=e=>{const b=e.target.closest('[data-office-action]');if(b)officeAction(b.dataset.officeAction);};$('officeBack').onclick=()=>officeHome(officeSection);

const officeUsers=document.createElement('section');officeUsers.id='officeUsers';officeUsers.hidden=true;officeUsers.innerHTML=`<p>One user directory for DESK, OFFICE and Operations. Permissions determine each user's access.</p><div class="officeUserColumns"><form id="officeAddUser"><h3>Add user</h3><label>User name<input name="name" maxlength="80" autocomplete="off" required></label><label>Password or 4-digit passcode<input name="password" type="password" minlength="4" maxlength="256" autocomplete="new-password" required></label><label>Confirm password<input name="confirm" type="password" minlength="4" maxlength="256" autocomplete="new-password" required></label><p>After creating the user, select a shared role below.</p><button>Add user</button><button type="reset">Clear</button></form><form id="officeUserRole"><h3>Assign a shared role</h3><label>User<select id="officeRoleUser" name="name" required></select></label><label>Role<select id="officeRoleChoice" name="role_id" required></select></label><p>Role assignments apply across Operations and retail applications.</p><button>Save role assignment</button><button type="reset">Clear</button></form></div><div class="officeUserListHeading"><h3>Shared user directory</h3><button type="button" id="officeUsersRefresh">Refresh users</button></div><div class="officeUserTable"><table><thead><tr><th>User</th><th>Role</th><th>Account</th></tr></thead><tbody id="officeUserRows"></tbody></table></div>`;$('officeWork').append(officeUsers);
let officeRoleData=null;
async function officeLoadUsers(){try{const [directory,roles]=await Promise.all([api('admin/users'),api('roles')]);officeRoleData=roles;const chosen=$('officeRoleUser').value;$('officeRoleUser').innerHTML='<option value="">Choose user</option>'+directory.users.filter(u=>!u.admin).map(u=>`<option value="${esc(u.name)}">${esc(u.name)}</option>`).join('');$('officeRoleUser').value=chosen;$('officeRoleChoice').innerHTML='<option value="">Choose role</option>'+roles.roles.map(r=>`<option value="${r.id}">${esc(r.name)}</option>`).join('');$('officeUserRows').innerHTML=directory.users.map(u=>`<tr><td>${esc(u.name)}</td><td>${u.admin?'Administrator':esc(roles.roles.find(r=>r.id===roles.assignments[u.name])?.name||'Individual permissions')}</td><td>${u.admin?'Administrator':'Staff'}</td></tr>`).join('');}catch(e){posMessage(e.message);}}
$('officeUsersRefresh').onclick=()=>{if(changedForms.has($('officeUserRole'))){posMessage('Save or clear the role selection before refreshing.');return;}officeLoadUsers();};
$('officeRoleUser').onchange=()=>{if(officeRoleData)$('officeRoleChoice').value=String(officeRoleData.assignments[$('officeRoleUser').value]||'');};
$('officeAddUser').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,f=form.elements;if(f.password.value!==f.confirm.value){posMessage('Passwords do not match.');return;}const data={name:f.name.value.trim(),password:f.password.value};const buttons=[...form.querySelectorAll('button')];buttons.forEach(b=>b.disabled=true);try{await api('user',data);form.reset();posMessage('User added to the shared directory. Assign a role to set their access.');await officeLoadUsers();$('officeRoleUser').value=data.name;}catch(error){posMessage(error.status?error.message:'Could not confirm creation. Refresh the shared user directory before trying again.');}finally{buttons.forEach(b=>b.disabled=false);}};
$('officeUserRole').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,button=e.submitter;button.disabled=true;try{await api('admin/user-role',{name:form.elements.name.value,role_id:Number(form.elements.role_id.value)});form.reset();posMessage('Shared role assignment saved.');await officeLoadUsers();}catch(error){posMessage(error.message);}finally{button.disabled=false;}};

