retailAppearanceButton.onclick=async()=>{
 if(!navigationAllowed()||unfinished()){posMessage('Save or clear current entries first.');return;}
 try{let settings=await api('account/retail-theme');const opts=selected=>Object.entries(retailThemeNames).map(([v,n])=>`<option value="${v}" ${v===selected?'selected':''}>${n}</option>`).join('');const d=flowModal('Appearance',`<form id="retailThemeForm"><label>My theme<select name="theme"><option value="default">Use store default</option>${opts(settings.theme)}</select></label><p>Saved with your user account and used in DESK and OFFICE. Changes apply immediately after saving.</p><button class="primary">Save my theme</button></form>${can('manage_pos')?`<hr><form id="retailDefaultThemeForm"><label>Store default<select name="theme">${opts(settings.default)}</select></label><p>Used when a user has not selected a personal theme. Other signed-in sessions receive it at their next sign-in.</p><button class="primary">Save store default</button></form>`:''}<p id="retailThemeStatus" role="status"></p>`);
 for(const form of d.querySelectorAll('form'))form.onsubmit=async e=>{e.preventDefault();const store=form.id==='retailDefaultThemeForm';try{settings=await api('account/retail-theme',{scope:store?'store':'user',theme:form.elements.theme.value,revision:store?settings.default_revision:settings.revision});changedForms.delete(form);applyRetailTheme(settings);$('retailThemeStatus').textContent='Theme saved.';}catch(e){d.querySelector('.flowError').textContent=e.message;}};
 }catch(e){posMessage(e.message);}
};

