function receiptDesignMarkup(design){return `${design.logo?`<img class="receiptLogo" src="${esc(design.logo)}" alt="Store logo">`:''}<p class="receiptContact">${esc(design.address||'')}<br>${esc(design.phone||'')}</p>`;}
