function customerReceiptEditor(){const design=structuredClone(customerConfig.receipt);$('flowOffice').innerHTML=`<div class="customerColumns"><form id="customerReceiptForm"><h3>Receipt appearance</h3><label>Store address<textarea name="address" maxlength="2000">${esc(design.address)}</textarea></label><label>Phone / contact details<input name="phone" value="${esc(design.phone)}" maxlength="2000"></label><label>Logo (PNG or JPEG, up to 200 KB)<input id="customerLogo" type="file" accept="image/png,image/jpeg"></label><button type="button" id="customerLogoClear">Remove logo</button><label>Return-policy text<textarea name="policy" maxlength="2000">${esc(design.policy)}</textarea></label><label>Receipt footer<textarea name="footer" maxlength="2000">${esc(design.footer)}</textarea></label><p>Used on new completed sales. Reprints retain the original receipt design; older receipts remain unchanged.</p><button class="primary">Save receipt design</button><button type="button" id="customerReceiptDiscard">Discard changes</button><p id="customerSaveStatus" role="status"></p></form><section class="customerPaper" aria-label="Receipt preview"><span class="customerPreviewLabel">LIVE PREVIEW · SAMPLE SALE</span><div id="customerReceiptPreview"></div></section></div>`;
 const form=$('customerReceiptForm');const read=()=>{for(const k of ['address','phone','policy','footer'])design[k]=form.elements[k].value;};const preview=()=>{read();$('customerReceiptPreview').innerHTML=receiptDesignMarkup(design)+`<h2>${esc(posOverview?.settings.store||'CoastYouth Retail')}</h2><p>Receipt #PREVIEW</p><hr><p>Adult shirt <span>$5.99</span></p><p>Paperback book <span>$3.99</span></p><hr><p>Subtotal <span>$9.98</span></p><p>Tax <span>$0.42</span></p><h3>Total <span>$10.40</span></h3><p>Cash <span>$20.00</span></p><p>Change <span>$9.60</span></p><hr><p class="receiptContact">${esc(design.policy)}</p><p class="receiptContact">${esc(design.footer)}</p>`;};form.oninput=preview;
 $('customerLogo').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(!['image/png','image/jpeg'].includes(file.type)||file.size>200000){$('customerSaveStatus').textContent='Choose a PNG or JPEG smaller than 200 KB.';return;}design.logo=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file);});changedForms.set(form,'logo changed');preview();};$('customerLogoClear').onclick=()=>{design.logo='';changedForms.set(form,'logo changed');preview();};$('customerReceiptDiscard').onclick=()=>{changedForms.delete(form);customerReceiptEditor();};form.onsubmit=async e=>{e.preventDefault();read();try{const r=await retailSave('customer-settings-save',{kind:'receipt',...design});customerConfig.receipt=r.settings;changedForms.delete(form);customerReceiptEditor();$('customerSaveStatus').textContent='Receipt design saved.';}catch(e){$('customerSaveStatus').textContent=e.message;}};preview();
}
function customerDisplayEditor(){const s=customerConfig.display;$('flowOffice').innerHTML=`<div class="customerColumns"><form id="customerDisplayForm"><h3>Second-screen checkout</h3><label><input type="checkbox" name="enabled" ${s.enabled?'checked':''}> Enable customer-facing displays</label><label>Welcome message<input name="welcome" maxlength="2000" value="${esc(s.welcome)}" required></label><label>Thank-you message<input name="thanks" maxlength="2000" value="${esc(s.thanks)}" required></label><p>In DESK, choose Customer display to pair this checkout with a browser window on the customer monitor. Pairing lasts 12 hours. Disabling displays revokes existing links.</p><p>The display shows only product names, quantities and totals. It clears the sale when the cashier connection is inactive or disconnected.</p><button class="primary">Save display settings</button><button type="button" id="customerDisplayDiscard">Discard changes</button><p id="customerSaveStatus" role="status"></p></form><section class="customerDisplaySample"><span>COASTYOUTH RETAIL</span><h2 id="customerWelcomePreview">${esc(s.welcome)}</h2><p>Your items will appear here.</p><div class="customerSampleTotal">Sample total <strong>$10.40</strong></div><p id="customerThanksPreview">${esc(s.thanks)}</p></section></div>`;const form=$('customerDisplayForm');form.oninput=()=>{$('customerWelcomePreview').textContent=form.elements.welcome.value;$('customerThanksPreview').textContent=form.elements.thanks.value;};$('customerDisplayDiscard').onclick=()=>{changedForms.delete(form);customerDisplayEditor();};form.onsubmit=async e=>{e.preventDefault();try{const r=await retailSave('customer-settings-save',{kind:'display',revision:s.revision,enabled:form.elements.enabled.checked,welcome:form.elements.welcome.value,thanks:form.elements.thanks.value});customerConfig.display=r.settings;changedForms.delete(form);customerDisplayEditor();$('customerSaveStatus').textContent='Customer display settings saved.';}catch(e){$('customerSaveStatus').textContent=e.message;}};}
async function customerEmailEditor(){const s=customerConfig.email;$('flowOffice').innerHTML=`<nav class="flowTabs"><button id="customerTemplatesTab" aria-pressed="true">Templates & delivery</button><button id="customerReservationsTab" aria-pressed="false">Reservations & history</button></nav><div id="customerEmailSettings"><div class="customerConnection"><strong>Google Workspace / Gmail</strong><span>${customerConfig.gmail_ready?'Credentials configured · delivery not yet verified':'Not connected · no email will be sent'}</span></div><div class="customerColumns"><form id="customerEmailForm"><fieldset ${user.admin?'':'disabled'}><label>Sending Gmail address<input name="sender" type="email" value="${esc(s.sender)}"></label><label>Sender name<input name="sender_name" maxlength="160" value="${esc(s.sender_name)}"></label><label><input name="enabled" type="checkbox" ${s.enabled?'checked':''}> Enable automatic delivery</label><label>Reminder lead time (hours)<input name="reminder_hours" type="number" min="1" max="168" value="${s.reminder_hours}"></label><label>Confirmation subject<input name="confirmation_subject" maxlength="160" value="${esc(s.confirmation_subject)}" required></label><label>Confirmation message<textarea name="confirmation_body" rows="5" required>${esc(s.confirmation_body)}</textarea></label><label>Reminder subject<input name="reminder_subject" maxlength="160" value="${esc(s.reminder_subject)}" required></label><label>Reminder message<textarea name="reminder_body" rows="5" required>${esc(s.reminder_body)}</textarea></label><button class="primary">Save email settings</button></fieldset><button type="button" id="customerEmailDiscard">Discard changes</button><p id="customerSaveStatus" role="status"></p></form><section><div class="customerPaper"><span class="customerPreviewLabel">MESSAGE PREVIEW · NO EMAIL SENT</span><label>Message type<select id="customerPreviewKind"><option value="confirmation">Confirmation</option><option value="reminder">Reminder</option></select></label><h3 id="customerSubjectPreview"></h3><p id="customerBodyPreview" class="receiptContact"></p></div><p>Template fields: {customer}, {type}, {start}, {end}, {address}, {store}.</p><p>Only reservations explicitly enabled in Reservations & history are enrolled. Canceled, completed, pending-request and past reservations are excluded. Reservation times use the server’s local timezone.</p><details><summary>Connect Gmail on the server</summary><p>An administrator must configure a Google app password in the server environment variable COASTYOUTH_GMAIL_APP_PASSWORD and restart the server. Use an app password, not your normal Google password. Google account policy and two-step verification determine availability. The sending address must match that account.</p><p>SMTP uses smtp.gmail.com, port 587, with verified TLS. Credentials are never returned to the browser or stored in reservation records. Sending settings require administrator access.</p><a href="https://knowledge.workspace.google.com/admin/gmail/send-email-from-a-printer-scanner-or-app" target="_blank" rel="noopener">Google setup instructions</a></details></section></div></div><div id="customerReservationPanel" hidden></div>`;
 const form=$('customerEmailForm');const preview=()=>{const kind=$('customerPreviewKind').value;for(const other of ['confirmation','reminder'])for(const part of ['subject','body'])form.elements[other+'_'+part].closest('label').hidden=other!==kind;const fields={customer:'Sample customer',type:'Delivery',start:'Nov 15, 2026 at 10:00 AM',end:'11:00 AM',address:'123 Sample Street',store:posOverview?.settings.store||'CoastYouth Retail'};const render=text=>text.replace(/\{(customer|type|start|end|address|store)\}/g,(_,k)=>fields[k]);$('customerSubjectPreview').textContent=render(form.elements[kind+'_subject'].value);$('customerBodyPreview').textContent=render(form.elements[kind+'_body'].value);};form.oninput=preview;$('customerPreviewKind').onchange=preview;preview();
 $('customerEmailDiscard').onclick=()=>{changedForms.delete(form);customerEmailEditor();};form.onsubmit=async e=>{e.preventDefault();try{const data=Object.fromEntries(new FormData(form));data.enabled=form.elements.enabled.checked;data.reminder_hours=Number(data.reminder_hours);const r=await retailSave('customer-settings-save',{kind:'email',revision:s.revision,...data});customerConfig.email=r.settings;changedForms.delete(form);await customerEmailEditor();$('customerSaveStatus').textContent='Email settings saved.';}catch(e){$('customerSaveStatus').textContent=e.message;}};
 $('customerTemplatesTab').onclick=()=>{if(changedForms.has($('customerContactForm')))return posMessage('Save communication preferences first.');$('customerEmailSettings').hidden=false;$('customerReservationPanel').hidden=true;$('customerTemplatesTab').setAttribute('aria-pressed','true');$('customerReservationsTab').setAttribute('aria-pressed','false');};$('customerReservationsTab').onclick=async()=>{if(changedForms.has(form))return posMessage('Save or discard template changes first.');$('customerEmailSettings').hidden=true;$('customerReservationPanel').hidden=false;$('customerTemplatesTab').setAttribute('aria-pressed','false');$('customerReservationsTab').setAttribute('aria-pressed','true');await customerReservationList();};
}
async function customerReservationList(){try{const data=await api('pos/reservation-messages');const root=$('customerReservationPanel');root.innerHTML=`<div class="customerConnection"><strong>${data.enabled&&data.gmail_ready?'Automatic delivery enabled':'Delivery paused'}</strong><span>Saving preferences queues messages; delivery requires enabled Gmail settings.</span></div><div class="customerColumns"><form id="customerContactForm"><h3>Reservation communication preferences</h3><label>Existing reservation<select name="job" required><option value="">Choose a reservation</option>${data.jobs.map(j=>`<option value="${esc(j.id)}">${esc(j.customer)} · ${esc(j.start)} · ${esc(j.status)}</option>`).join('')}</select></label><label>Customer email<input name="email" type="email" required></label><label><input type="checkbox" name="confirmations"> Confirmation and schedule-change emails</label><label><input type="checkbox" name="reminders"> Reservation reminder</label><p>Confirm the address with the customer. These settings do not edit their reservation.</p><button class="primary">Save communication preferences</button><button type="button" id="customerPreviewReservation">Preview confirmation</button><button type="button" id="customerContactDiscard">Discard changes</button><p id="customerContactStatus" role="status"></p></form><section class="customerPaper"><span class="customerPreviewLabel">RESERVATION MESSAGE PREVIEW</span><h3 id="customerReservationSubject">Choose a reservation</h3><p id="customerReservationBody" class="receiptContact">Preview a message before enabling communication.</p></section></div><h3>Delivery history</h3><div class="flowTable"><table><thead><tr><th>Recipient</th><th>Message</th><th>Status</th><th>Scheduled</th><th>Details</th></tr></thead><tbody>${data.deliveries.map(r=>`<tr><td>${esc(r.recipient)}</td><td>${esc(r.kind)}</td><td>${esc(r.status)}</td><td>${esc(new Date(r.due*1000).toLocaleString())}</td><td>${esc(r.error)}${['failed','uncertain'].includes(r.status)?`<button data-delivery-retry="${r.id}">Review retry</button>`:''}</td></tr>`).join('')||'<tr><td colspan="5">No messages queued yet.</td></tr>'}</tbody></table></div><button id="customerHistoryRefresh">Refresh history</button>`;
 const form=$('customerContactForm');let revision=0;form.elements.job.onchange=()=>{const contact=data.jobs.find(j=>j.id===form.elements.job.value)?.contact;revision=contact?.revision||0;form.elements.email.value=contact?.email||'';form.elements.confirmations.checked=!!contact?.confirmations;form.elements.reminders.checked=!!contact?.reminders;};$('customerContactDiscard').onclick=()=>{changedForms.delete(form);customerReservationList();};$('customerHistoryRefresh').onclick=()=>{if(changedForms.has(form))return posMessage('Save or discard preferences first.');customerReservationList();};$('customerPreviewReservation').onclick=async()=>{try{const r=await retailSave('reservation-preview',{job:form.elements.job.value,kind:'confirmation'});$('customerReservationSubject').textContent=r.subject;$('customerReservationBody').textContent=r.text;}catch(e){$('customerContactStatus').textContent=e.message;}};
 form.onsubmit=async e=>{e.preventDefault();try{await retailSave('reservation-contact',{job:form.elements.job.value,revision,email:form.elements.email.value,confirmations:form.elements.confirmations.checked,reminders:form.elements.reminders.checked});changedForms.delete(form);await customerReservationList();$('customerContactStatus').textContent='Preferences saved. Existing reservation unchanged.';}catch(e){$('customerContactStatus').textContent=e.message;}};
 root.querySelectorAll('[data-delivery-retry]').forEach(button=>button.onclick=()=>{const d=flowModal('Review delivery retry','<p>Check the sender’s Gmail Sent folder first. An uncertain message may already have been sent.</p><label><input id="customerRetryChecked" type="checkbox"> I checked Gmail Sent and confirmed a retry is needed.</label><button class="primary" id="customerRetryConfirm">Queue retry</button>');$('customerRetryConfirm').onclick=async()=>{try{await retailSave('delivery-retry',{id:Number(button.dataset.deliveryRetry),checked_sent:$('customerRetryChecked').checked});d.close();d.remove();await customerReservationList();}catch(e){d.querySelector('.flowError').textContent=e.message;}};});
 }catch(e){$('customerReservationPanel').textContent=e.message;}}
const customerPairButton=document.createElement('button');customerPairButton.id='customerPair';customerPairButton.textContent='Customer display';customerPairButton.hidden=officeMode;document.querySelector('.headerRight').append(customerPairButton);
let customerPairToken=null,customerDisplayBusy=false;
customerPairButton.onclick=async()=>{if(!user)return;try{const r=await retailSave('display-pair',{});customerPairToken=r.token;const url=new URL(r.path,location.origin).href;const d=flowModal('Open the customer screen',`<p>Open this limited-access display on the customer monitor, then select Full screen. Use a separate browser profile without a staff login on customer-accessible touchscreens. Pairing lasts 12 hours. Keep this link on your store’s devices.</p><label>Display link<input id="customerPairLink" readonly value="${esc(url)}"></label><a id="customerOpenDisplay" href="${esc(url)}" target="_blank" rel="noopener">Open customer display</a><p>Only this checkout’s products and totals are shared.</p>`);await customerDisplaySync();}catch(e){posMessage(e.message);}};
async function customerDisplaySync(){if(!customerPairToken||customerDisplayBusy)return;customerDisplayBusy=true;try{await api('pos/display-state',{token:customerPairToken,cart:user&&$('posReceipt').hidden?posCurrent?.id||null:null,sale:user&&!$('posReceipt').hidden?posLastReceipt?.id||null:null});}catch(e){if(e.status===404||e.status===401)customerPairToken=null;}finally{customerDisplayBusy=false;}}
setInterval(customerDisplaySync,2000);

